schemas.schema-02-actors.prisma:
/// Anonymous guest users who can browse and view published articles,
/// comments, and attachments without requiring authentication or
/// registration. Guests represent the general public accessing economic and
/// political discussion content. This table tracks guest-level interactions
/// and access patterns for platform analytics, though guests have no
/// personal information or managed entities.
///
/// @namespace Actors
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model economic_discussion_board_guests {
  //----
  // COLUMNS
  //----
  /// Primary Key.
  id String @id

  /// Timestamp when the guest record was created for tracking access patterns.
  created_at DateTime

  /// Timestamp when the guest record was last updated.
  updated_at DateTime

  /// Soft delete timestamp to mark inactive guest records.
  deleted_at DateTime?
}

/// Registered member users who can create articles with attachments, post
/// comments, and participate actively in economic and political discussions.
/// Members have authenticated accounts with secure password-based login and
/// can manage their own content independently. They represent the core
/// community of contributors who require email verification and session
/// management for platform access and content creation permissions.
///
/// @namespace Actors
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model economic_discussion_board_members {
  //----
  // COLUMNS
  //----
  /// Primary Key.
  id String @id

  /// Member's email address used for authentication and account management.
  /// Must be unique across all members.
  email String

  /// Hashed password for secure authentication. Stored using industry-standard
  /// hashing algorithms.
  password_hash String

  /// Timestamp when the member account was created.
  created_at DateTime

  /// Timestamp when the member account was last updated.
  updated_at DateTime

  /// Soft delete timestamp to mark deactivated member accounts while
  /// preserving content history.
  deleted_at DateTime?

  //----
  // RELATIONS
  //----
  economic_discussion_board_member_sessions economic_discussion_board_member_sessions[]
  economic_discussion_board_articles economic_discussion_board_articles[]
  economic_discussion_board_comments economic_discussion_board_comments[]

  @@unique([email])
}

/// Administrator users with elevated permissions to manage platform content,
/// moderate inappropriate material, and oversee user accounts. Admins have
/// authenticated accounts with secure login and can perform administrative
/// actions across all platform content including articles, comments, and
/// user management. They maintain platform integrity and community standards
/// through content review and moderation capabilities.
///
/// @namespace Actors
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model economic_discussion_board_admins {
  //----
  // COLUMNS
  //----
  /// Primary Key.
  id String @id

  /// Administrator's email address used for authentication and account
  /// management. Must be unique across all administrators.
  email String

  /// Hashed password for secure authentication. Stored using industry-standard
  /// hashing algorithms.
  password_hash String

  /// Timestamp when the administrator account was created.
  created_at DateTime

  /// Timestamp when the administrator account was last updated.
  updated_at DateTime

  /// Soft delete timestamp to mark removed administrator accounts.
  deleted_at DateTime?

  //----
  // RELATIONS
  //----
  economic_discussion_board_admin_sessions economic_discussion_board_admin_sessions[]

  @@unique([email])
}

/// Authentication sessions for member users, tracking login activity and
/// connection details for security monitoring and audit purposes. Sessions
/// are managed through member login/logout processes and include connection
/// metadata for platform security. Each session expires after inactivity or
/// explicit logout, ensuring secure access control for member accounts.
///
/// @namespace Actors
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model economic_discussion_board_member_sessions {
  //----
  // COLUMNS
  //----
  /// Primary Key.
  id String @id

  /// Belonged member's {@link economic_discussion_board_members.id}.
  economic_discussion_board_member_id String

  /// IP address from which the member logged in.
  ip String

  /// URL where the login session originated.
  href String

  /// Referrer URL for tracking login source.
  referrer String

  /// Timestamp when the session was created at login.
  created_at DateTime

  /// Timestamp when the session expired or was terminated.
  expired_at DateTime?

  //----
  // RELATIONS
  //----
  member economic_discussion_board_members @relation(fields: [economic_discussion_board_member_id], references: [id], onDelete: Cascade)

  economic_discussion_board_comments economic_discussion_board_comments[]

  // spellchecker: ignore-next-line
  @@index([economic_discussion_board_member_id, created_at], map: "economic_discussion_board_member_sessions_economic_dis_099c537f")
}

/// Authentication sessions for administrator users, recording login details
/// and administrative access for security auditing and system monitoring.
/// Admin sessions track critical platform access and include connection
/// information for compliance and security review. Sessions automatically
/// expire and are audited for administrative accountability.
///
/// @namespace Actors
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model economic_discussion_board_admin_sessions {
  //----
  // COLUMNS
  //----
  /// Primary Key.
  id String @id

  /// Belonged admin's {@link economic_discussion_board_admins.id}.
  economic_discussion_board_admin_id String

  /// IP address from which the administrator logged in.
  ip String

  /// URL where the administrative login originated.
  href String

  /// Referrer URL for tracking administrative login source.
  referrer String

  /// Timestamp when the administrative session was created.
  created_at DateTime

  /// Timestamp when the administrative session expired.
  expired_at DateTime?

  //----
  // RELATIONS
  //----
  admin economic_discussion_board_admins @relation(fields: [economic_discussion_board_admin_id], references: [id], onDelete: Cascade)

  // spellchecker: ignore-next-line
  @@index([economic_discussion_board_admin_id, created_at], map: "economic_discussion_board_admin_sessions_economic_disc_eba1ce0f")
}

schemas.schema-03-articles.prisma:
/// Core content unit where members publish articles on economic and
/// political topics. Each article serves as the foundation for discussion,
/// containing title and body text that can be enhanced with various
/// attachments for supporting evidence and data.
///
/// @namespace Articles
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model economic_discussion_board_articles {
  //----
  // COLUMNS
  //----
  /// Primary Key.
  id String @id

  /// Authenticated member who created this article. {@link
  /// economic_discussion_board_members.id}
  economic_discussion_board_member_id String

  /// Article title limited to 200 characters for concise topic identification.
  title String

  /// Main article content supporting rich text formatting and up to 10,000
  /// characters for comprehensive economic analysis.
  body String

  /// Publication status indicating article state: draft, pending (awaiting
  /// moderation), published (visible to all), rejected (moderation denied).
  status String

  /// Timestamp when the article was first created.
  created_at DateTime

  /// Timestamp when the article was last modified.
  updated_at DateTime

  /// Soft delete timestamp for removed articles.
  deleted_at DateTime?

  //----
  // RELATIONS
  //----
  creator economic_discussion_board_members @relation(fields: [economic_discussion_board_member_id], references: [id], onDelete: Cascade)

  economic_discussion_board_attachments economic_discussion_board_attachments[]
  economic_discussion_board_comments economic_discussion_board_comments[]

  // spellchecker: ignore-next-line
  @@index([economic_discussion_board_member_id, created_at], map: "economic_discussion_board_articles_economic_discussion_410152b4")
}

/// Supporting materials attached to articles, including images and documents
/// that provide visual evidence or data sources for economic discussions.
/// Each attachment belongs to exactly one article.
///
/// @namespace Articles
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model economic_discussion_board_attachments {
  //----
  // COLUMNS
  //----
  /// Primary Key.
  id String @id

  /// Associated article this attachment supports. {@link
  /// economic_discussion_board_articles.id}
  economic_discussion_board_article_id String

  /// Original filename of the uploaded attachment.
  name String

  /// Storage path or URL where the attachment file is located.
  path String

  /// File type of the attachment (e.g., 'image/jpeg', 'application/pdf').
  type String

  /// File size in bytes for storage management.
  size Int

  /// Timestamp when the attachment was uploaded.
  created_at DateTime

  /// Timestamp when the attachment was last modified.
  updated_at DateTime

  //----
  // RELATIONS
  //----
  article economic_discussion_board_articles @relation(fields: [economic_discussion_board_article_id], references: [id], onDelete: Cascade)

  // spellchecker: ignore-next-line
  @@index([economic_discussion_board_article_id], map: "economic_discussion_board_attachments_economic_discuss_90086b70")
}

schemas.schema-04-comments.prisma:
/// User comments on published articles enabling threaded discussions and
/// community engagement. Each comment belongs to a specific article and is
/// created by an authenticated member through their active session. Comments
/// can have parent references to create nested reply threads up to 3 levels
/// deep. Members can edit their own comments after posting, and
/// administrators can moderate inappropriate content through soft deletion.
/// Comments appear immediately upon submission but may be moderated by
/// admins, maintaining chronological ordering within discussion threads.
///
/// @namespace Comments
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model economic_discussion_board_comments {
  //----
  // COLUMNS
  //----
  /// Primary Key.
  id String @id

  /// Belonged article's {@link economic_discussion_board_articles.id}.
  economic_discussion_board_article_id String

  /// Commented member's {@link economic_discussion_board_members.id}.
  economic_discussion_board_member_id String

  /// Belonged member's authentication session's {@link
  /// economic_discussion_board_member_sessions.id}.
  economic_discussion_board_member_session_id String

  /// Parent comment's {@link economic_discussion_board_comments.id} for
  /// threaded replies.
  parent_id String?

  /// Comment text content with maximum length of 2000 characters for
  /// meaningful discussion contributions.
  body String

  /// Timestamp when the comment was first created and published.
  created_at DateTime

  /// Timestamp when the comment was last modified by the author.
  updated_at DateTime

  /// Soft delete timestamp for moderated content removal while preserving
  /// audit trails.
  deleted_at DateTime?

  //----
  // RELATIONS
  //----
  article economic_discussion_board_articles @relation(fields: [economic_discussion_board_article_id], references: [id], onDelete: Cascade)
  member economic_discussion_board_members @relation(fields: [economic_discussion_board_member_id], references: [id], onDelete: Cascade)
  session economic_discussion_board_member_sessions @relation(fields: [economic_discussion_board_member_session_id], references: [id], onDelete: Cascade)
  parent economic_discussion_board_comments? @relation("recursive", fields: [parent_id], references: [id], onDelete: Cascade)

  recursive economic_discussion_board_comments[] @relation("recursive")

  // spellchecker: ignore-next-line
  @@index([economic_discussion_board_member_session_id], map: "economic_discussion_board_comments_economic_discussion_8951c09d")

  // spellchecker: ignore-next-line
  @@index([economic_discussion_board_article_id, created_at], map: "economic_discussion_board_comments_economic_discussion_d27d64bf")
  // spellchecker: ignore-next-line
  @@index([economic_discussion_board_member_id, created_at], map: "economic_discussion_board_comments_economic_discussion_78f87a3c")
  @@index([parent_id, created_at])
}

